(x, y, t) => {
  const cx = 240, cy = 120;
  const wx = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.22)*12 + Math.sin((x+y)*0.008+t*0.15)*8;
  const wy = Math.cos(y*0.02-t*0.27)*16 + Math.sin(x*0.016+t*0.33)*11 + Math.cos((x-y)*0.009-t*0.18)*7;
  const sx = x+wx, sy = y+wy;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9],
    [80+Math.sin(t*0.45+3)*110, 40+Math.cos(t*0.65+4)*55, 0.11, 2.1],
    [400+Math.cos(t*0.55+2)*85, 200+Math.sin(t*0.75+1)*65, 0.065, 2.4]
  ];
  let aS=0, iS=0, cS=0;
  for (const [sX,sY,f,sp] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS += Math.sin(d*f-t*sp);
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5);
    cS += Math.sin(d*f*1.3-t*sp*0.8+3.0)*0.5;
  }
  const act=aS/8, inh=iS/8, cor=cS/8;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2
    + Math.sin(sx*0.07*Math.cos(t*0.1)+sy*0.05*Math.sin(t*0.13)+t*0.6)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4
    + Math.sin(dist*0.08+ang*2-t*2.5)*0.2;
  const reaction = Math.tanh((act-inh*0.7+cor*0.3+bg*0.25+spiral)*2.2);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5+Math.sin(sx*0.22-sy*0.18+t*1.3)*0.3)*1.5)*0.3;
  const micro = Math.sin(sx*0.4+t*3)*Math.sin(sy*0.35-t*2.5)*0.08;
  const blend = reaction*0.6+cell*0.25+micro*0.15, v = blend*0.5+0.5;
  const pal = [
    [5,12,52],[10,40,85],[15,75,105],[20,120,130],[45,155,125],
    [120,175,95],[190,180,70],[210,155,80],[195,110,75],[165,65,70],
    [120,35,65],[70,20,60],[30,12,55],[5,12,52]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.75+Math.sin(reaction*Math.PI)*0.25;
  const edge=Math.abs(reaction)>0.65?1.2:Math.abs(reaction)>0.4?1.05:0.95;
  const glow = Math.max(0, Math.abs(reaction)-0.8)*3;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*40)|0),
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*25)|0),
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*15)|0)
  ];
}
